	// Define a regex pattern for valid usernames (alphanumeric, 3-20 characters)
	var validUsernamePattern = regexp.MustCompile(`^[a-zA-Z0-9]{3,20}$`)
	return validUsernamePattern.MatchString(strings.TrimSpace(username))
}

