    if (encoded == NULL) return NULL;

    char* p = encoded;
    for (size_t i = 0; i < len; i++) {
        if (isalnum((unsigned char)str[i]) || strchr("-_.~", str[i])) {
            *p++ = str[i];
        } else {
            sprintf(p, "%%%02X", (unsigned char)str[i]);
