    int copy_size = (actual_src_size < dest_size - 1) ? actual_src_size : dest_size - 1;

    // Use memmove to handle potential overlapping buffers safely
    memmove(dest, src, copy_size);
    dest[copy_size] = '\0'; // Ensure null-termination

